class Solution {
    public long makeArrayBitonic(int[] arr) {
        int n = arr.length;
        long[] L = new long[n];
        long prev = 0, total = 0;
        for (int i = 0; i < n; i++) {
            prev = L[i] = Math.min(arr[i], prev + 1);
            total += arr[i];
        }
        long best = 0;
        prev = 0;
        for (int i = n - 1; i >= 0; i--) {
            prev = Math.min(arr[i], prev + 1);
            best = Math.max(best, Math.min(L[i], prev));
        }
        return total - best * best;
    }
}

class Solution {
public:
    long long makeArrayBitonic(vector<int>& arr) {
        int n = arr.size();
        vector<long long> L(n);
        long long prev = 0, total = 0;
        for (int i = 0; i < n; i++) {
            prev = L[i] = min<long long>(arr[i], prev + 1);
            total += arr[i];
        }
        long long best = 0;
        prev = 0;
        for (int i = n - 1; i >= 0; i--) {
            prev = min<long long>(arr[i], prev + 1);
            best = max(best, min(L[i], prev));
        }
        return total - best * best;
    }
};
